-- Bind confirmed ticket reservations to one instance-owned waiting room.
-- The reserved quantity is applied to the normal server seat; ticket grids
-- remain generated by the existing game engine at ticket selection/start.

ALTER TABLE game_sessions
  ADD COLUMN room_code text NULL REFERENCES rooms(room_code) ON DELETE RESTRICT;
CREATE UNIQUE INDEX game_sessions_room_code_key ON game_sessions(room_code) WHERE room_code IS NOT NULL;

ALTER TABLE ticket_reservations
  ADD COLUMN player_id text NULL REFERENCES players(player_id) ON DELETE RESTRICT,
  ADD COLUMN room_code text NULL REFERENCES rooms(room_code) ON DELETE RESTRICT,
  ADD CONSTRAINT ticket_reservations_assignment_pair_check
    CHECK ((player_id IS NULL) = (room_code IS NULL)),
  ADD CONSTRAINT ticket_reservations_session_player_key UNIQUE(session_id, player_id);
CREATE INDEX ticket_reservations_player_idx ON ticket_reservations(player_id) WHERE player_id IS NOT NULL;

ALTER TABLE room_members
  ADD COLUMN booking_reservation_id uuid NULL REFERENCES ticket_reservations(reservation_id) ON DELETE RESTRICT;
CREATE UNIQUE INDEX room_members_booking_reservation_key ON room_members(booking_reservation_id)
  WHERE booking_reservation_id IS NOT NULL;

ALTER TABLE ticket_reservation_audit DROP CONSTRAINT ticket_reservation_audit_action_check;
ALTER TABLE ticket_reservation_audit ADD CONSTRAINT ticket_reservation_audit_action_check
  CHECK (action IN ('session.create','session.update','session.open','session.pause','session.cancel','session.complete',
    'hold.create','hold.confirm','hold.cancel','hold.expire','hold.assign'));

CREATE FUNCTION validate_game_session_room_binding() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  room_instance text;
  room_status text;
  room_game integer;
BEGIN
  IF NEW.room_code IS NULL THEN
    IF TG_OP = 'UPDATE' AND OLD.room_code IS NOT NULL AND EXISTS (
      SELECT 1 FROM ticket_reservations WHERE session_id=OLD.session_id AND player_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'a session with assigned reservations cannot be detached from its room';
    END IF;
    RETURN NEW;
  END IF;
  SELECT game_instance_id,status,game_number INTO room_instance,room_status,room_game
    FROM rooms WHERE room_code=NEW.room_code;
  IF room_instance IS NULL THEN RAISE EXCEPTION 'session room does not exist'; END IF;
  IF room_instance IS DISTINCT FROM NEW.instance_id THEN RAISE EXCEPTION 'session room belongs to another instance'; END IF;
  IF room_status <> 'WAITING' OR room_game <> 0 OR EXISTS (SELECT 1 FROM games WHERE room_code=NEW.room_code) THEN
    RAISE EXCEPTION 'session room must not have started a game';
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER game_sessions_room_binding_guard BEFORE INSERT OR UPDATE OF room_code,instance_id ON game_sessions
  FOR EACH ROW EXECUTE FUNCTION validate_game_session_room_binding();

CREATE FUNCTION validate_ticket_reservation_assignment() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  session_room text;
  session_instance text;
  room_instance text;
BEGIN
  IF NEW.player_id IS NULL THEN RETURN NEW; END IF;
  SELECT room_code,instance_id INTO session_room,session_instance
    FROM game_sessions WHERE session_id=NEW.session_id;
  SELECT game_instance_id INTO room_instance FROM rooms WHERE room_code=NEW.room_code;
  IF NEW.status <> 'confirmed' THEN RAISE EXCEPTION 'only confirmed reservations may be assigned'; END IF;
  IF session_room IS NULL OR session_room IS DISTINCT FROM NEW.room_code THEN RAISE EXCEPTION 'reservation room does not match its session'; END IF;
  IF room_instance IS NULL OR room_instance IS DISTINCT FROM session_instance THEN RAISE EXCEPTION 'reservation instance does not match its room'; END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER ticket_reservations_assignment_guard BEFORE INSERT OR UPDATE OF player_id,room_code,status ON ticket_reservations
  FOR EACH ROW EXECUTE FUNCTION validate_ticket_reservation_assignment();

CREATE FUNCTION validate_room_member_booking_reservation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  reservation_player text;
  reservation_room text;
  reservation_status text;
BEGIN
  IF NEW.booking_reservation_id IS NULL THEN RETURN NEW; END IF;
  SELECT player_id,room_code,status INTO reservation_player,reservation_room,reservation_status
    FROM ticket_reservations WHERE reservation_id=NEW.booking_reservation_id;
  IF reservation_player IS DISTINCT FROM NEW.player_id OR reservation_room IS DISTINCT FROM NEW.room_code OR reservation_status <> 'confirmed' THEN
    RAISE EXCEPTION 'booking reservation does not match this room seat';
  END IF;
  RETURN NEW;
END; $$;
CREATE TRIGGER room_members_booking_guard BEFORE INSERT OR UPDATE OF booking_reservation_id,room_code,player_id ON room_members
  FOR EACH ROW EXECUTE FUNCTION validate_room_member_booking_reservation();
